package net.civeira.phylax.feature.observe.observedembed.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedembed.domain.ObservedEmbed;
import net.civeira.phylax.feature.observe.observedembed.domain.valueobject.MinRefreshVO;

class MinRefreshValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of min refresh of observed embed")
  void test_min_refresh_value_holder_assign_plain_value() {
    Object holder = new Object();
    MinRefreshValueHolder<Object> value = new MinRefreshValueHolder<>(holder);
    Assertions.assertSame(holder, value.minRefresh(1), "Setters must return the holder");
    Assertions.assertTrue(value.getMinRefreshValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getMinRefresh().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of min refresh of observed embed")
  void test_min_refresh_value_holder_assign_value_object() {
    Object holder = new Object();
    MinRefreshValueHolder<Object> value = new MinRefreshValueHolder<>(holder);
    MinRefreshVO vo = MinRefreshVO.from(1);
    Assertions.assertFalse(value.getMinRefreshValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.minRefresh(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMinRefreshValue().orElseThrow());
    Assertions.assertSame(holder, value.minRefresh(Optional.empty()));
    Assertions.assertFalse(value.getMinRefreshValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.minRefresh(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMinRefreshValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of min refresh of observed embed against the original")
  void test_min_refresh_value_holder_read() {
    Object holder = new Object();
    MinRefreshValueHolder<Object> value = new MinRefreshValueHolder<>(holder);
    MinRefreshVO vo = MinRefreshVO.from(1);
    MinRefreshVO other = MinRefreshVO.from(1);
    ObservedEmbed original = Mockito.mock(ObservedEmbed.class);
    Mockito.when(original.getMinRefreshValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMinRefresh(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readMinRefresh(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.minRefresh(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMinRefresh(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMinRefresh(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of min refresh of observed embed")
  void test_min_refresh_value_holder_unset() {
    Object holder = new Object();
    MinRefreshValueHolder<Object> value = new MinRefreshValueHolder<>(holder);
    MinRefreshVO vo = MinRefreshVO.from(1);
    value.minRefresh(vo);
    Assertions.assertSame(holder, value.unsetMinRefreshIfMatches("minRefresh_other"));
    Assertions.assertTrue(value.getMinRefreshValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMinRefreshIfMatches("minRefresh"));
    Assertions.assertFalse(value.getMinRefreshValue().isPresent(),
        "The field name must clear the value");
    value.minRefresh(vo);
    Assertions.assertSame(holder, value.unsetMinRefresh());
    Assertions.assertFalse(value.getMinRefreshValue().isPresent(), "Unset must clear the value");
  }
}
